const GRILLE_KM = {10:250,20:250,30:250,40:320,50:350,60:390,70:430,80:500,90:540,100:580,110:620,120:660,130:700,140:740,150:780,160:820,170:860,180:900};
const COEFF_SAISONNALITE = {1:-0.07,2:-0.07,3:+0.10,4:+0.10,5:+0.15,6:+0.15,7:+0.10,8:-0.07,9:0.00,10:0.00,11:-0.07,12:0.00};
const COEFF_URGENCE = {DD_PRIORITAIRE:+0.10,DD_URGENT:+0.05,DD_NORMAL:-0.05,DD_3MOISETPLUS:-0.10};
const TRANCHES_CAPACITE = [[0,19,-0.05],[19,53,0.00],[53,63,+0.15],[63,67,+0.20],[67,85,+0.40]];
const MARGE=0.15,TVA=0.10,PRIX_KM_LONG=2.5;

function arrondir_km(km){return Math.ceil(km/10)*10;}
function prix_base_simple(d){if(d<=0)throw new Error('Distance doit être > 0');if(d>850)throw new Error('Distance irréaliste: '+d+' km');if(d<=180){const k=arrondir_km(d);const p=GRILLE_KM[k];if(!p)throw new Error('Pas de tarif pour '+k+' km');return{prix:p,source:'Grille forfait ('+k+' km)'};}const p=(d*2)*PRIX_KM_LONG;return{prix:p,source:'Hors grille ('+d+' km × 2 × '+PRIX_KM_LONG+' €/km)'};}  
function get_coeff_saisonnalite(date){const d=new Date(date);if(isNaN(d))throw new Error('Date invalide: '+date);const m=d.getMonth()+1;return{coeff:COEFF_SAISONNALITE[m],label:'Mois '+m+' → '+(COEFF_SAISONNALITE[m]*100).toFixed(0)+'%'};}
function get_coeff_urgence(u){const c=COEFF_URGENCE[u];if(c===undefined)throw new Error('Code urgence invalide: '+u);return{coeff:c,label:u+' → '+(c*100).toFixed(0)+'%'};}
function get_coeff_capacite(n){if(n<=0)throw new Error('Passagers doit être > 0');if(n>85)throw new Error('Max 85 passagers');for(const[min,max,c]of TRANCHES_CAPACITE){if(n>min&&n<=max)return{coeff:c,label:n+' passagers ('+( min+1)+'–'+max+') → '+(c*100).toFixed(0)+'%'};}throw new Error('Aucune tranche pour '+n+' passagers');}

const donnees=$json.donnees;
if(!donnees)throw new Error('Pas de données dans $json.donnees');
const{nb_passagers,date_depart,date_demande,distance_km,aller_retour,urgence,options={}}=donnees;
if(!nb_passagers)throw new Error('Manquant: nb_passagers');
if(!date_depart)throw new Error('Manquant: date_depart');
if(!date_demande)throw new Error('Manquant: date_demande');
if(!distance_km)throw new Error('Manquant: distance_km');
if(!urgence)throw new Error('Manquant: urgence');

const lignes=[];
const{prix:base_simple,source}=prix_base_simple(distance_km);
lignes.push({libelle:'Base transfert — '+source,montant:base_simple});
let base=base_simple;
if(aller_retour){base=base_simple*2;lignes.push({libelle:'Aller/Retour (× 2)',montant:base});}
const mm=base*MARGE,am=base+mm;
lignes.push({libelle:'Marge (+'+( MARGE*100).toFixed(0)+'%)',montant:mm});
const{coeff:cs,label:ls}=get_coeff_saisonnalite(date_depart);
const ms=am*cs,as2=am+ms;
lignes.push({libelle:'Saisonnalité — '+ls,montant:ms});
const{coeff:cu,label:lu}=get_coeff_urgence(urgence);
const mu=as2*cu,au=as2+mu;
lignes.push({libelle:'Urgence — '+lu,montant:mu});
const{coeff:cc,label:lc}=get_coeff_capacite(nb_passagers);
const mc=au*cc,ac=au+mc;
lignes.push({libelle:'Capacité — '+lc,montant:mc});
let tot_opts=0;
if(options.nb_guides>0){const m=options.nb_guides*80*(options.nb_jours||1);tot_opts+=m;lignes.push({libelle:options.nb_guides+' guide(s) × 80€',montant:m});}
if(options.nb_nuits_chauffeur>0){const m=options.nb_nuits_chauffeur*120;tot_opts+=m;lignes.push({libelle:options.nb_nuits_chauffeur+' nuit(s) chauffeur × 120€',montant:m});}
if(options.peages_inclus)lignes.push({libelle:'Péages inclus',montant:0});
const prix_ht=Math.round((ac+tot_opts)*100)/100;
lignes.push({libelle:'─── SOUS-TOTAL HT',montant:prix_ht});
const tva=Math.round(prix_ht*TVA*100)/100;
lignes.push({libelle:'TVA ('+( TVA*100).toFixed(0)+'%)',montant:tva});
const prix_ttc=Math.round((prix_ht+tva)*100)/100;
return{prix_ht,tva,prix_ttc,devise:'EUR',lignes,coefficients:{marge:'+'+(MARGE*100).toFixed(0)+'%',saisonnalite:ls,urgence:lu,capacite:lc},meta:{distance_km,aller_retour:aller_retour||false,nb_passagers,date_depart,date_demande,calcule_le:new Date().toISOString()}};

const data = $json;
const urgence = data.donnees?.urgence || "DD_NORMAL";
const delaiJours = (urgence === "DD_PRIORITAIRE" || urgence === "DD_URGENT") ? 2 : 3;
const dateRelance = new Date(Date.now() + delaiJours * 86400000).toISOString().split('T')[0];
return { 
  delai_jours: delaiJours, 
  date_relance: dateRelance, 
  email: data.donnees?.email || "", 
  nom_societe: data.donnees?.nom_societe || "", 
  prix_ttc: $node["Calculer devis"].json.prix_ttc 
};

const output = $json.output;
try {
  const cleaned = output.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  const parsed = JSON.parse(cleaned);

  // Force la date_demande à aujourd'hui côté système
  if (parsed.donnees) {
    parsed.donnees.date_demande = new Date().toISOString().split('T')[0];

    // Recalcule l'urgence avec la vraie date
    if (parsed.donnees.date_depart) {
      const depart = new Date(parsed.donnees.date_depart);
      const demande = new Date();
      const diffJours = Math.floor((depart - demande) / (1000 * 60 * 60 * 24));

      if (diffJours < 2) parsed.donnees.urgence = 'DD_PRIORITAIRE';
      else if (diffJours < 7) parsed.donnees.urgence = 'DD_URGENT';
      else if (diffJours < 90) parsed.donnees.urgence = 'DD_NORMAL';
      else parsed.donnees.urgence = 'DD_3MOISETPLUS';
    }
  }

  return parsed;
} catch(e) {
  return { statut: "incomplet", message: output };
}

const donnees = $node["Code"].json.donnees;
const devis = $node["Calculer devis"].json;

const ref = 'NTR-' + Date.now();
const filename = 'devis-NeoTravel-' + ref + '.pdf';

// PDF minimal en pur texte
const content = `DEVIS NEOTRAVEL
Ref: ${ref}
Client: ${donnees.nom_societe || ''}
Email: ${donnees.email || ''}
Trajet: ${donnees.ville_depart} -> ${donnees.ville_arrivee}
Passagers: ${donnees.nb_passagers}
Date: ${donnees.date_depart}
Prix HT: ${devis.prix_ht} EUR
TVA: ${devis.tva} EUR
Prix TTC: ${devis.prix_ttc} EUR
Devis valable 30 jours.`;

const pdf_base64 = Buffer.from(content, 'utf8').toString('base64');

return [{ json: { pdf_base64: pdf_base64, filename: filename, ref: ref } }];

